usage_examples:
// Requires: rn *raft.RawNode, st *raft.MemoryStorage, d *rafttest.RawNodeDriver
if d.HasReady() {
    rd := d.Next()
    _ = st.Append(rd.Entries)
    d.Advance(rd)
}
_ = d.Cache().Messages()

// Requires: env *rafttest.InteractionEnv
if err := env.ProcessReady(0); err != nil {
    panic(err)
}
m, ok := env.TakeMsg(func(m raftpb.Message) bool { return m.Type == raftpb.MsgVote })
_ = ok
_ = m

// Requires: env *rafttest.InteractionEnv
if err := env.ProcessReady(0); err != nil {
    panic(err)
}
if err := env.DeliverMsg(func(m raftpb.Message) bool {
    return m.Type == raftpb.MsgVote && m.To == 2
}); err != nil {
    panic(err)
}

// Requires: d *rafttest.RawNodeDriver, peer *raft.RawNode
m, ok := d.Cache().Take(func(m raftpb.Message) bool { return m.Type == raftpb.MsgVote })
if ok {
    if err := peer.Step(m); err != nil {
        panic(err)
    }
}
